draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.fill();
  ctx.stroke();

  // Draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-80);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-70);
  ctx.stroke();

  // Apply wisdom lesson
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply', W/2, H/2-200 + 50 * Math.sin(t));

  // Life and lesson text
  ctx.font = '18px Arial';
  ctx.fillText('Life', W/2-60 + 20 * Math.cos(t), H/2-50);
  ctx.fillText('Lesson', W/2+40 + 20 * Math.cos(t), H/2-50);

  ctx.restore();
}
